289	     * Builds the owner's customer code as {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
290	     * region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'}) via
291	     * {@link OwnerMapper#toRegion}, and {@code HASH8} is the first 8 upper-case hex characters of the
292	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}).
293	     *
294	     * <p>When the computed code collides with an existing owner's {@code customerCode}, it is
295	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it
296	     * unique (e.g. {@code NSW-1A2B3C4D-2}); the de-duplicated code is returned. Absent a collision the
297	     * base region-and-hash code is returned unchanged.
298	     *
299	     * @param owner the owner being created, with its region-determining postcode and city populated
300	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
301	     * @return the (de-duplicated) region-and-hash customer code for the owner being created
302	     */
303	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
304	        String region = ownerMapper.toRegion(owner);
305	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
306	        String baseCode = region + "-" + hash8;
307	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
308	            .map(Owner::getCustomerCode)
309	            .filter(java.util.Objects::nonNull)
310	            .collect(java.util.stream.Collectors.toSet());
311	        if (!existingCodes.contains(baseCode)) {
312	            return baseCode;
313	        }
314	        int n = 2;
315	        while (existingCodes.contains(baseCode + "-" + n)) {
316	            n++;
317	        }
318	        return baseCode + "-" + n;
319	    }
