323	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
324	     */
325	    private static String sha256Hex8(String value) {
326	        try {
327	            byte[] digest = MessageDigest.getInstance("SHA-256")
328	                .digest(value.getBytes(StandardCharsets.UTF_8));
329	            StringBuilder sb = new StringBuilder();
330	            for (byte b : digest) {
331	                sb.append(String.format("%02X", b));
332	            }
333	            return sb.substring(0, 8);
334	        }
335	        catch (NoSuchAlgorithmException e) {
336	            throw new IllegalStateException("SHA-256 not available", e);
337	        }
338	    }
