388	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
389	     * owners' stored numbers when detecting duplicates.
390	     */
391	    private static String toE164(String telephone) {
392	        if (telephone == null) {
393	            return null;
394	        }
395	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
396	        String digits;
397	        if (cleaned.startsWith("+")) {
398	            digits = cleaned.substring(1);
399	        } else {
400	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
401	            digits = "61" + national;
402	        }
403	        if (!digits.matches("[0-9]{8,15}")) {
404	            return null;
405	        }
406	        if (!hasValidNationalLength(digits)) {
407	            return null;
408	        }
409	        return "+" + digits;
