414	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
415	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
416	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
417	     */
418	    private static boolean hasValidNationalLength(String digits) {
419	        if (digits.startsWith("61")) {
420	            return digits.length() - 2 == 9;
421	        }
422	        if (digits.startsWith("1")) {
423	            return digits.length() - 1 == 10;
