486	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
487	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
488	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
489	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
490	        ownerDto.setMembershipPoints(points);
491	        ownerDto.setMembershipLevel(OwnerMapper.membershipLevelFor(points));
492	        return ownerDto;
493	    }
494	
495	    /**
496	     * Returns the number of owners sharing the given {@code householdId} (the household's size),
497	     * counting every existing owner that carries the same {@code householdId}. Returns {@code 0} when
498	     * {@code householdId} is {@code null}, since an owner with no postcode has no household key and so
499	     * no household.
500	     *
501	     * @param householdId the owner's computed household identifier, or {@code null} when absent
502	     * @return the number of owners in the household
503	     */
504	    private int householdSize(String householdId) {
505	        if (householdId == null) {
506	            return 0;
507	        }
508	        return (int) this.clinicService.findAllOwners().stream()
509	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
510	            .count();
511	    }
512	
513	    /**
514	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
515	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
516	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
517	     */
518	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
519	        if (registrationDate == null) {
520	            return false;
521	        }
522	        long registeredThatDay = this.clinicService.findAllOwners().stream()
523	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
524	            .count();
525	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
526	    }
527	
528	    private void requireDailyLimitNotReached(LocalDate businessDay) {
529	        long registeredThatDay = this.clinicService.findAllOwners().stream()
530	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
531	            .count();
532	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
533	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
534	        }
535	    }
536	
537	    /**
538	     * Fixed list of public holidays. A registration date landing on one of these dates is rolled
539	     * forward, just like a weekend, until it reaches a non-holiday business day.
540	     */
541	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
542	        LocalDate.of(2026, 1, 1),
543	        LocalDate.of(2026, 1, 26),
544	        LocalDate.of(2026, 4, 25),
545	        LocalDate.of(2026, 12, 25),
546	        LocalDate.of(2026, 12, 28));
547	
548	    /**
549	     * Rolls {@code date} forward to a business day: while it falls on a Saturday, Sunday, or a listed
550	     * public holiday it advances one day at a time until it reaches a non-holiday weekday. Applied to
551	     * the effective registration date (whether supplied in the request or defaulted to the server date)
552	     * so a weekend or holiday registration is recorded on the next business day, and every value derived
553	     * from the registration date uses the adjusted date.
554	     *
555	     * @param date the effective registration date (supplied or defaulted), never {@code null}
556	     * @return the same date, or the next non-holiday business day when {@code date} is a weekend or holiday
557	     */
558	    private static LocalDate toBusinessDay(LocalDate date) {
559	        LocalDate adjusted = date;
560	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
561	            adjusted = adjusted.plusDays(1);
562	        }
563	        return adjusted;
564	    }
565	
566	    /** Whether {@code date} falls on a Saturday or Sunday. */
567	    private static boolean isWeekend(LocalDate date) {
568	        DayOfWeek day = date.getDayOfWeek();
569	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
570	    }
571	
572	    /** Matches a well-formed postcode: exactly four decimal digits. */
573	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
574	
575	    /**
576	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
577	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
578	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
579	     * present here and accepts any well-formed postcode.
580	     */
581	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
582	        "NSW", new int[] {2000, 2099},
583	        "VIC", new int[] {3000, 3099},
584	        "QLD", new int[] {4000, 4099});
585	
586	    /**
587	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
588	     * optional, so the request contract stays backward-compatible). When present it must be exactly
589	     * four digits and, for a city whose region is known, fall within that region's inclusive range
590	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
591	     * postcode. A malformed or out-of-range value is rejected with a 400.
592	     *
593	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
594	     * @param city the owner's city, used to look up the region whose range constrains the postcode
595	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
596	     */
597	    private void validatePostcode(String postcode, String city) {
598	        if (postcode == null) {
599	            return;
600	        }
601	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
602	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
603	        }
604	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
605	        int[] range = REGION_POSTCODES.get(region);
606	        if (range == null) {
607	            return;
608	        }
609	        int value = Integer.parseInt(postcode);
610	        if (value < range[0] || value > range[1]) {
611	            throw new InvalidFieldValueException("postcode",
612	                "Postcode must be valid for the city's region " + region);
613	        }
614	    }
615	
616	    /**
617	     * Validates an owner's optional {@code registrationDate}. When absent nothing is checked (the
618	     * date defaults to the server date). When present it must not be later than the current server
619	     * date: a registration cannot be recorded in the future, so a future date is rejected with a 400.
620	     *
621	     * @param registrationDate the supplied registration date (may be {@code null} when not supplied)
622	     * @throws InvalidFieldValueException if the supplied date is later than the server date
623	     */
624	    private void validateRegistrationDate(LocalDate registrationDate) {
625	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
626	            throw new InvalidFieldValueException("registrationDate",
627	                "Registration date must not be later than the current date");
628	        }
629	    }
630	
631	    private void requireCityBelowCapacity(String city) {
632	        long cityOwners = this.clinicService.findAllOwners().stream()
633	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
634	            .count();
635	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
636	            throw new CityAtCapacityException(city);
637	        }
638	    }
639	
640	    /**
641	     * Rejects the request when the incoming owner's derived {@code identityKey} exactly matches that
642	     * of any existing owner. The key ({@code normalizedTelephone + '|' + (email or empty) + '|' +
643	     * (householdId or empty)}) is the single consolidated duplicate-detection key that replaces the
644	     * former separate telephone, email and household checks. Because the telephone is part of the
645	     * key, two members of the same household (same {@code householdId}) with different telephones
646	     * have different keys and are both allowed; only an exact full-key match is a duplicate. The key
647	     * is derived identically for the incoming and existing owners via {@link OwnerMapper#toIdentityKey}.
648	     *
649	     * @param owner the incoming owner, with its normalized telephone, email and household identifier
650	     *              already populated
651	     * @throws DuplicateIdentityException if another owner already has this exact identity key
652	     */
653	    private void requireUniqueIdentity(Owner owner) {
654	        String identityKey = ownerMapper.toIdentityKey(owner);
655	        boolean taken = this.clinicService.findAllOwners().stream()
656	            .filter(existing -> !isDeleted(existing))
657	            .map(ownerMapper::toIdentityKey)
658	            .anyMatch(identityKey::equals);
659	        if (taken) {
660	            throw new DuplicateIdentityException(identityKey);
661	        }
662	    }
663	
664	    /**
665	     * Returns whether an existing owner has been soft-deleted. A soft-deleted owner retains its row
666	     * but is ignored by the create endpoint's duplicate and identity checks, so a normally-blocking
667	     * duplicate is allowed when the only matching owner has been deleted.
668	     */
669	    private static boolean isDeleted(Owner owner) {
670	        return Boolean.TRUE.equals(owner.getDeleted());
671	    }
672	
673	    /**
674	     * Rejects the request when the incoming owner would join an existing household, unless the owner
675	     * has opted in via {@code sharesHousehold}. Because the household is keyed on {@code householdId}
676	     * (the computed hash of the normalized last name and postcode), any existing owner carrying the
677	     * same {@code householdId} is a member of the same household, so a second such owner is a
678	     * household duplicate. Setting {@code sharesHousehold} bypasses this block, declaring the owner a
679	     * genuine additional member of that household. An owner with no {@code householdId} (no postcode,
680	     * so no household key) is never a household duplicate.
681	     *
682	     * @param owner the incoming owner, with its computed {@code householdId} already populated
683	     * @param sharesHousehold whether the request opted in to joining an existing household
684	     * @throws DuplicateIdentityException if the household already exists and the owner did not opt in
685	     */
686	    private void requireNoHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
687	        if (sharesHousehold) {
688	            return;
689	        }
690	        String householdId = owner.getHouseholdId();
691	        if (householdId == null) {
692	            return;
693	        }
694	        boolean householdExists = this.clinicService.findAllOwners().stream()
695	            .filter(existing -> !isDeleted(existing))
696	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
697	        if (householdExists) {
698	            throw new DuplicateIdentityException(ownerMapper.toIdentityKey(owner));
699	        }
700	    }
701	
702	    /**
703	     * Flags the incoming owner as a possible (soft) duplicate. Called after the hard-duplicate and
704	     * household-duplicate checks have passed, so the owner is known not to be a rejected duplicate.
705	     * When an existing owner shares this owner's household (same computed {@code householdId}) but
706	     * carries a different telephone, the owner is a possible duplicate: {@code possibleDuplicate} is
707	     * set {@code true} and {@code possibleDuplicateOf} to that existing owner's id (the earliest such
708	     * owner by id when more than one matches). Otherwise both are cleared. A declared household member
709	     * ({@code sharesHousehold} true) is never flagged: it is a deliberate member, not a suspected
710	     * duplicate. An owner with no {@code householdId} never matches, since it shares no household.
711	     *
712	     * @param owner the incoming owner, with its computed {@code householdId} and telephone populated
713	     * @param sharesHousehold whether the request opted in as a declared household member
714	     */
715	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
716	        owner.setPossibleDuplicate(false);
717	        owner.setPossibleDuplicateOf(null);
718	        if (sharesHousehold) {
719	            return;
720	        }
721	        String householdId = owner.getHouseholdId();
722	        if (householdId == null) {
723	            return;
724	        }
725	        String telephone = owner.getTelephone();
726	        this.clinicService.findAllOwners().stream()
727	            .filter(existing -> householdId.equals(existing.getHouseholdId())
728	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
729	            .min(java.util.Comparator.comparing(Owner::getId))
730	            .ifPresent(match -> {
731	                owner.setPossibleDuplicate(true);
732	                owner.setPossibleDuplicateOf(match.getId());
733	            });
734	    }
735	
736	    /**
737	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
738	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
739	     * comparisons are case-insensitive.
740	     */
741	    private static String normalizeForHousehold(String value) {
742	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
743	    }
744	
745	    /**
746	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
747	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
748	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
749	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
750	     * value normalizes to the empty string, so the required-field check rejects an address that is
751	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
752	     *
753	     * @param address the raw address value from the request (may be {@code null})
754	     * @return the normalized address, or the empty string when blank after normalization
755	     */
756	    private static String normalizeAddress(String address) {
757	        if (address == null) {
758	            return "";
759	        }
760	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
761	        if (collapsed.isEmpty()) {
762	            return "";
763	        }
764	        String[] tokens = collapsed.split(" ");
765	        StringBuilder sb = new StringBuilder();
766	        for (String token : tokens) {
767	            String expanded = switch (token) {
768	                case "ST" -> "STREET";
769	                case "RD" -> "ROAD";
770	                case "AVE" -> "AVENUE";
771	                default -> token;
772	            };
773	            if (sb.length() > 0) {
774	                sb.append(' ');
775	            }
776	            sb.append(expanded);
777	        }
778	        return sb.toString();
779	    }
780	
781	    /**
782	     * Composes the stored/returned {@code address} from the normalized structured lines: the
783	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
784	     * appended when {@code addressLine2} is present (non-empty). Both arguments are already
785	     * normalized via {@link #normalizeAddress(String)}.
786	     *
787	     * @param normalizedAddressLine1 the normalized first address line (non-empty)
788	     * @param normalizedAddressLine2 the normalized second address line, or the empty string when absent
789	     * @return the composed address string
790	     */
791	    private static String composeAddress(String normalizedAddressLine1, String normalizedAddressLine2) {
792	        if (normalizedAddressLine2.isEmpty()) {
793	            return normalizedAddressLine1;
794	        }
795	        return normalizedAddressLine1 + " " + normalizedAddressLine2;
796	    }
797	
798	    /**
799	     * Derives the stable household identifier for an owner from its last name and postcode as the
800	     * upper-cased first 12 hex characters of the SHA-256 digest of
801	     * {@code normalizedLastName + '|' + postcode}, where the last name is normalized (trimmed,
802	     * internal whitespace collapsed, lower-cased) so casing and spacing do not affect it. Because the
803	     * identifier is a deterministic function of the normalized last name and postcode, owners that
804	     * share a last name and postcode share the identifier automatically — no back-fill or opt-in is
805	     * required. Returns {@code null} when no postcode is present, since the household is keyed on the
806	     * postcode and there is then nothing to key on.
807	     *
808	     * @param lastName the owner's last name (already validated non-blank)
809	     * @param postcode the owner's postcode (a validated 4-digit value, or {@code null} when absent)
810	     * @return the 12-hex-character household identifier, or {@code null} when no postcode is present
811	     */
812	    private static String householdIdFor(String lastName, String postcode) {
813	        if (postcode == null || postcode.isBlank()) {
814	            return null;
815	        }
816	        String normalizedLastName = normalizeForHousehold(lastName);
817	        try {
818	            byte[] digest = MessageDigest.getInstance("SHA-256")
819	                .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
820	            StringBuilder sb = new StringBuilder();
821	            for (byte b : digest) {
822	                sb.append(String.format("%02X", b));
823	            }
824	            return sb.substring(0, 12);
825	        }
826	        catch (NoSuchAlgorithmException e) {
827	            throw new IllegalStateException("SHA-256 not available", e);
828	        }
829	    }
830	}
